// Start from the items included in `start_from`. We've mostly only translated items accessible
// from that, but some passes render items inaccessible again, which we filter out here.
deps.unprocessed = ctx
    .translated
    .all_items()
    .filter(|item| {
        ctx.options
            .start_from
            .iter()
            .any(|pat| pat.matches(&ctx.translated, item.item_meta()))
    })
    .map(|item| item.id())
    .collect();

// Explore reachable items.

impl StartFrom {
    pub fn matches(&self, ctx: &TranslatedCrate, item_meta: &ItemMeta) -> bool {
        match self {
            StartFrom::Pattern { pattern, .. } => pattern.matches(ctx, &item_meta.name),
            StartFrom::Attribute(attr) => item_meta
                .attr_info
                .attributes
                .iter()
                .filter_map(|a| a.as_unknown())
                .any(|raw_attr| raw_attr.path == *attr),
            StartFrom::Pub => item_meta.attr_info.public && item_meta.is_local,
        }

impl PatElem {
    fn matches_with_generics(
        &self,
        ctx: &TranslatedCrate,
        elem: &PathElem,
        args: Option<&GenericArgs>,
    ) -> bool {
        match (self, elem) {
            (PatElem::Glob, _) => true,
            (
                PatElem::Ident {
                    name: pat_ident,
                    generics,
                    ..
                },
                PathElem::Ident(ident, _),
            ) => {
                // `crate` is a special keyword that referes to the current crate.
                let same_ident =
                    pat_ident == ident || (pat_ident == "crate" && ident == &ctx.crate_name);
                same_ident && PatTy::matches_generics(ctx, generics, args)
            }
            (PatElem::Impl(_pat), PathElem::Impl(ImplElem::Ty(..))) => {
                // TODO
                false
            }
            (PatElem::Impl(pat), PathElem::Impl(ImplElem::Trait(impl_id))) => {
                let Some(timpl) = ctx.trait_impls.get(*impl_id) else {
                    return false;
                };
                let trait_name = ctx.item_name(timpl.impl_trait.id);
                pat.matches_with_generics(ctx, trait_name, Some(&timpl.impl_trait.generics))
            }
            _ => false,
        }
    }
}
